CREATE TABLE IF NOT EXISTS public.website_services (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL,
  draft_content jsonb NOT NULL,
  published_content jsonb,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  display_order integer NOT NULL DEFAULT 0 CHECK (display_order >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT website_services_slug_unique UNIQUE (slug),
  CONSTRAINT website_services_draft_object_check CHECK (jsonb_typeof(draft_content) = 'object'),
  CONSTRAINT website_services_published_object_check CHECK (
    published_content IS NULL OR jsonb_typeof(published_content) = 'object'
  )
);

CREATE INDEX IF NOT EXISTS website_services_public_order_idx
  ON public.website_services (display_order, created_at)
  WHERE status = 'published';
CREATE UNIQUE INDEX IF NOT EXISTS website_services_published_slug_unique
  ON public.website_services ((published_content->>'slug'))
  WHERE status = 'published';

ALTER TABLE public.website_services ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.website_services FROM anon, authenticated, PUBLIC;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.website_services TO service_role;

