UPDATE public.website_services AS service
SET draft_content = jsonb_set(service.draft_content, '{displayOrder}', to_jsonb(seeded_services.display_order), true),
    published_content = jsonb_set(service.published_content, '{displayOrder}', to_jsonb(seeded_services.display_order), true)
FROM seeded_services
WHERE service.id = seeded_services.id;

